import numpy as np

# Count adjacent same-color pairs (each adjacency counts once)
def count_adjacencies(grid, color):
    """Count number of adjacent cell pairs of a given color"""
    pairs = []
    h_pairs = []
    v_pairs = []
    for r in range(10):
        for c in range(9):
            if grid[r][c] == color and grid[r][c+1] == color:
